import{c as t,Q as o,j as r,m as e}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"其他综合-数学基础","description":"","frontmatter":{"title":"其他综合-数学基础"},"headers":[],"relativePath":"综合知识/其他综合/数学基础.md","filePath":"综合知识/其他综合/数学基础.md","lastUpdated":null}'),l={name:"综合知识/其他综合/数学基础.md"};function n(i,a,h,s,d,c){return o(),r("div",null,[...a[0]||(a[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 最小生成树（n 节点需 n-1 条边，不产生环路）</li><li>[x] 最短路径</li><li>[x] 网络与最大流量</li><li>[x] 线性规划</li><li>[x] 动态规划</li><li>[x] 博弈论</li><li>[x] 决策论（决策树/期望货币价值）</li><li>[x] 数学建模</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h2 id="图论应用" tabindex="-1">图论应用 <a class="header-anchor" href="#图论应用" aria-label="Permalink to &quot;图论应用&quot;">​</a></h2><h3 id="最小生成树" tabindex="-1">最小生成树 <a class="header-anchor" href="#最小生成树" aria-label="Permalink to &quot;最小生成树&quot;">​</a></h3><blockquote><p>将 n 个节点连通，至少需要 <strong>n-1 条边</strong>，同时<strong>不产生环路</strong>。</p></blockquote><p><strong>解题思路</strong>：从最小的边开始选，判断是否产生环路 → 不产生则选定 → 继续找次小的边 → 直到选出 n-1 条边为止。总成本 = 所有选定边的权重之和。</p><hr><h3 id="最短路径" tabindex="-1">最短路径 <a class="header-anchor" href="#最短路径" aria-label="Permalink to &quot;最短路径&quot;">​</a></h3><blockquote><p>求从起点到终点的最短路径，与关键路径（最长路径）相反。</p></blockquote><p><strong>解题方向</strong>：</p><ul><li>求项目最短工期 → <strong>关键路径法</strong>（最长路径）</li><li>求路径最短距离 → <strong>最短路径算法</strong>（Dijkstra 等）</li></ul><p><strong>直接计算法</strong>：逐层计算每个节点的最短距离，最终得到终点最短距离。</p><hr><h3 id="网络与最大流量" tabindex="-1">网络与最大流量 <a class="header-anchor" href="#网络与最大流量" aria-label="Permalink to &quot;网络与最大流量&quot;">​</a></h3><blockquote><p>求从源点到汇点通过网络的最大流量，受各段容量限制。</p></blockquote><p><strong>解题思路</strong>：找到所有从源到汇的路径，标注每条路径的瓶颈容量（该路径上最小容量的边），依次叠加并减去已用容量，直到无法找到新路径。</p><hr><h2 id="运筹方法" tabindex="-1">运筹方法 <a class="header-anchor" href="#运筹方法" aria-label="Permalink to &quot;运筹方法&quot;">​</a></h2><h3 id="线性规划" tabindex="-1">线性规划 <a class="header-anchor" href="#线性规划" aria-label="Permalink to &quot;线性规划&quot;">​</a></h3><blockquote><p>在约束条件下求目标函数的最大值或最小值。</p></blockquote><p><strong>解题思路</strong>：列出约束条件不等式组 → 画出可行域 → 在顶点处求目标函数值 → 比较得出最优解。</p><hr><h3 id="动态规划" tabindex="-1">动态规划 <a class="header-anchor" href="#动态规划" aria-label="Permalink to &quot;动态规划&quot;">​</a></h3><blockquote><p>将复杂问题分解为子问题，通过求解子问题逐步得到最优解。核心特征：<strong>最优子结构</strong>和<strong>重叠子问题</strong>。</p></blockquote><p><strong>解题思路</strong>：定义状态 → 写出状态转移方程 → 自底向上/自顶向下求解。</p><hr><h3 id="伏格尔法" tabindex="-1">伏格尔法 <a class="header-anchor" href="#伏格尔法" aria-label="Permalink to &quot;伏格尔法&quot;">​</a></h3><h3 id="博弈论" tabindex="-1">博弈论 <a class="header-anchor" href="#博弈论" aria-label="Permalink to &quot;博弈论&quot;">​</a></h3><blockquote><p>研究决策主体行为发生直接相互作用时的决策及均衡问题。</p></blockquote><p><strong>基本要素</strong>：参与人、策略、收益、均衡（如纳什均衡：任一参与人单独改变策略都不会获得更多收益）。</p><hr><h3 id="状态转移矩阵" tabindex="-1">状态转移矩阵 <a class="header-anchor" href="#状态转移矩阵" aria-label="Permalink to &quot;状态转移矩阵&quot;">​</a></h3><h3 id="排队论" tabindex="-1">排队论 <a class="header-anchor" href="#排队论" aria-label="Permalink to &quot;排队论&quot;">​</a></h3><h3 id="决策论" tabindex="-1">决策论 <a class="header-anchor" href="#决策论" aria-label="Permalink to &quot;决策论&quot;">​</a></h3><blockquote><p>在不确定环境下进行方案选择的数学方法。</p></blockquote><p><strong>决策树分析</strong>：画出决策树 → 计算每个分支的期望值（概率 × 收益）→ 选择期望值最大的方案。</p><p><strong>期望货币价值分析</strong>：EMV = Σ（每种结果的概率 × 该结果的货币价值）。</p><hr><h2 id="数学建模" tabindex="-1">数学建模 <a class="header-anchor" href="#数学建模" aria-label="Permalink to &quot;数学建模&quot;">​</a></h2><p><strong>口诀</strong>：模型假设 → 模型建立 → 模型求解 → 模型分析 → 模型检验 → 模型应用。</p>',41)])])}const b=t(l,[["render",n]]);export{p as __pageData,b as default};
